use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let rows = input.as_array().unwrap();
    let mut sorted_rows = Vec::new();
    for row in rows {
        let key = row.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let value = row.as_array().unwrap().get(1).unwrap().as_i64().unwrap();
        sorted_rows.push((key, value));
    }
    sorted_rows.sort_unstable_by(|a, b| {
        if a.0 == b.0 {
            a.1.cmp(&b.1)
        } else {
            a.0.cmp(&b.0)
        }
    });
    let mut result = Value::Array;
    for (key, value) in sorted_rows {
        result.push(Value::Number(serde_json::Number::from(key)));
        result.push(Value::Number(serde_json::Number::from(value)));
    }
    result
}
